#include <stdio.h>

/* teste do desafio o-passeio — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: sem captura de stdout. Os tres cenarios usam a MESMA lista
   e entregam papeis DIFERENTES (o inicio, o meio e a ultima gaveta):
   quem somar sempre a partir da gaveta 0, ou quem somar a lista inteira
   ignorando o n, falha em pelo menos um cenario. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int oPasseio(const int *p, int n);

SM_TEST(o_passeio_inteiro) {
    int notas[5] = {3, 1, 4, 1, 5};
    checa_int("a soma das cinco notas", oPasseio(notas, 5), 14,
              "o nome da lista ja e o endereco da gaveta 0: o passeio anda as cinco");
}

SM_TEST(o_passeio_que_comeca_no_meio) {
    int notas[5] = {3, 1, 4, 1, 5};
    checa_int("a soma das tres ultimas", oPasseio(&notas[2], 3), 10,
              "o papel entregue aponta para a gaveta 2: o passeio comeca ali, em 4 + 1 + 5");
}

SM_TEST(o_passeio_de_uma_gaveta_so) {
    int notas[5] = {3, 1, 4, 1, 5};
    checa_int("a soma de uma nota so", oPasseio(&notas[4], 1), 5,
              "com n = 1 o passeio le a gaveta apontada e para");
}

solutionCode:
#include <stdio.h>

int oPasseio(const int *p, int n) {
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += *(p + i);
    }
    return total;
}
